async def act(page):
    """
    1) Use the site-visible search helper `create_curated_collection_by_search` to search for the target article.
    2) Find the search-result entry whose title matches the requested article title.
    3) Navigate to that article (prefer a relative goto when possible).
    4) Inspect accessible images (page.get_by_role('img')) and nearby captions/parent text for the substring "getty" (case-insensitive).
    5) Print exactly "Yes" if any evidence of Getty Images is found, otherwise print exactly "No".
    """
    import urllib.parse

    target_title = "One in three using AI for emotional support and conversation, UK says"

    # 1) Use the site-aware search helper to perform the visible search. This helper navigates to '/'.
    results = await create_curated_collection_by_search(page, target_title, max_results=50)

    # 2) Find a matching result by case-insensitive substring match, fallback to exact match
    target_url = None
    if isinstance(results, list):
        for item in results:
            if not isinstance(item, dict):
                continue
            title = (item.get('title') or '').strip()
            if title and target_title.lower() in title.lower():
                target_url = item.get('url')
                break
        if not target_url:
            for item in results:
                if not isinstance(item, dict):
                    continue
                title = (item.get('title') or '').strip()
                if title and title.lower() == target_title.lower():
                    target_url = item.get('url')
                    break

    if not target_url:
        # Article not found in search results
        print("No")
        return

    # 3) Navigate to the article URL using a relative goto when appropriate
    try:
        if target_url.startswith('/'):
            await page.goto(target_url)
        else:
            parsed = urllib.parse.urlparse(target_url)
            current = urllib.parse.urlparse(page.url)
            if parsed.netloc == '' or parsed.netloc == current.netloc:
                rel = parsed.path or '/'
                if parsed.query:
                    rel += '?' + parsed.query
                await page.goto(rel)
            else:
                await page.goto(target_url)
    except Exception:
        print("No")
        return

    # 4) Allow content to settle: prefer main visible, fallback to networkidle
    try:
        await page.get_by_role('main').wait_for(state='visible', timeout=5000)
    except Exception:
        try:
            await page.wait_for_load_state('networkidle')
        except Exception:
            pass

    # 5) Inspect images using accessibility-role-centric selectors
    found_getty = False
    img_locator = page.get_by_role('img')
    try:
        img_count = await img_locator.count()
    except Exception:
        img_count = 0

    for i in range(img_count):
        img = img_locator.nth(i)

        # Check accessible attributes for Getty mention
        try:
            alt = (await img.get_attribute('alt')) or ''
        except Exception:
            alt = ''
        try:
            aria_label = (await img.get_attribute('aria-label')) or ''
        except Exception:
            aria_label = ''
        try:
            title_attr = (await img.get_attribute('title')) or ''
        except Exception:
            title_attr = ''

        for txt in (alt, aria_label, title_attr):
            if txt and 'getty' in txt.lower():
                found_getty = True
                break
        if found_getty:
            break

        # Evaluate nearby caption (figcaption) or parent text for Getty mention
        try:
            nearby_text = await img.evaluate(
                "el => { const fig = el.closest('figure'); if (fig) { const cap = fig.querySelector('figcaption'); if (cap) return cap.innerText || ''; return fig.innerText || ''; } const p = el.parentElement; if (p) return p.innerText || ''; return el.alt || ''; }"
            )
            if nearby_text and 'getty' in nearby_text.lower():
                found_getty = True
                break
        except Exception:
            pass

    # 6) Last resort: scan main region visible text for Getty credit
    if not found_getty:
        try:
            main = page.get_by_role('main')
            main_count = await main.count()
            if main_count:
                try:
                    main_text = await main.nth(0).inner_text()
                except Exception:
                    main_text = ''
                if main_text and 'getty' in main_text.lower():
                    found_getty = True
        except Exception:
            pass

    # 7) Print result exactly as required
    print("Yes" if found_getty else "No")

